"""Build only exact-source reviewed parameter rows; refuse to change approved artifacts."""
import json, hashlib, re, fitz
from pathlib import Path
B=Path(__file__).resolve().parent; R=B.parents[3]
read=lambda p:json.loads(p.read_text(encoding='utf8'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
inventory=read(B/'source-inventory.json'); sources={Path(s['path']).stem:s for s in inventory['sources']}; artifacts=[]
for row in read(B/'setup-parameters.json'):
 t=row['target']; p=row['parameters']; s=sources[row['source_id']]; pdf=Path(s['path']); assert sha(pdf)==s['sha256']; book=fitz.open(pdf)
 assert len(p)==5 and row['author_review']=='EXACT_SOURCE_TEXT_AND_RENDERED_ADJUSTER_TABLES_CHECKED'
 out=B/f"{t['model_year']}-{t['model'].lower()}-damping-baseline-v1.procedure.json"
 if out.exists():assert read(out)['publication_status']!='APPROVED','Frozen artifact: create a new reviewed version'
 steps=[]; url=s['url']
 def step(id,title,instruction,pages,record=True):
  steps.append(dict(id=id,title=title,instruction=instruction,depends_on=[steps[-1]['id']] if steps else [],source_pdf_pages=sorted(set(pages)),source_links=[url+'#page='+str(n) for n in sorted(set(pages))],diagram_reference_required=True,record_required=record,verification=['Record the actual setting or inspection result requested before continuing.'] if record else ['Confirm the described check is complete.'],origin='Exact-year OEM adjustment instructions; saved original/final settings are an authored workflow adaptation.'))
 def control_pages(key):
  n=p[key]['pdf_page']; pages=[n]
  if t['model_year']>2020 and key in ['fork_rebound','fork_compression','shock_high_speed']:pages.append(n+1)
